import * as THREE from 'three'
import { film } from './film'
import type { EnvLook } from './scenes'

// The environment the glass and the cap reflect. One PMREM per EnvLook: an
// equirectangular picture from public/env/ when the file exists (generated by
// scripts/gen-assets.mjs), otherwise a small procedural studio built for that
// look. The rig exposes the texture of the dominant look; Experience.tsx hands
// it to scene.environment when it changes, never per frame.

export type EnvWeights = Record<EnvLook, number>

export type EnvRig = {
  /** Environment of the dominant look. Read after update(); assign to scene.environment when it changes. */
  texture: THREE.Texture
  /** Pick the dominant look. Cheap: a max over eight numbers. */
  update(renderer: THREE.WebGLRenderer, weights: EnvWeights): void
  /** Build the procedural environments ahead of time, one per task, so no beat pays for its PMREM mid-scroll. */
  prewarm(): void
  dispose(): void
}

/** Cube size every PMREM uses; equirect files are 2048 wide so three derives 512 for them. */
const PMREM_SIZE = 512

export const ENV_LOOKS: readonly EnvLook[] = ['void', 'mountain', 'teal', 'pale', 'highkey', 'spotlight', 'studio', 'underwater']

/** Equirect file per look (null: procedural only). Looks that share a file share one PMREM. */
const FILES: Readonly<Record<EnvLook, string | null>> = {
  void: 'studio-dark',
  mountain: 'studio-dark',
  teal: 'studio-dark',
  // a glossy cap under a wide softbox reads as silver; the spotlight beat reflects three small hard lights instead
  spotlight: null,
  studio: 'studio-dark',
  pale: 'studio-pale',
  // the alkaline beat: built here, with black flags (a generated pale studio has nothing dark to reflect)
  highkey: null,
  underwater: 'underwater-env',
}

type Procedural = {
  ground: string
  sky: string
  floor: string
  key: [string, number]
  rim: [string, number]
  keySize?: [number, number]
  /** front fill (behind the camera): what a surface facing the viewer reflects. Default: the sky at half strength. */
  fill?: [string, number]
  /**
   * Black flags: two tall dark boards beside and a little behind the subject. Glass reflects them at its
   * grazing edges (a dark rim that draws the silhouette on a white ground) and a black lacquer cap keeps
   * its black instead of mirroring a white room.
   */
  flags?: string
}

/** Procedural fallback: a dark or pale box, one big softbox, one strip light. Colors are sRGB hex, lights scaled. */
const PROCEDURAL: Readonly<Record<EnvLook, Procedural>> = {
  void: { ground: '#0b1218', sky: '#101a26', floor: '#05080c', key: ['#dfe9f0', 2.6], rim: ['#9fd0e0', 1.8] },
  mountain: { ground: '#0d1622', sky: '#243244', floor: '#06090d', key: ['#e4ecf2', 3], rim: ['#9fd0e0', 2] },
  teal: { ground: '#06161e', sky: '#0f2a36', floor: '#03090d', key: ['#cfe6ee', 2.4], rim: ['#7fc0d4', 2.2] },
  spotlight: { ground: '#05070c', sky: '#05070c', floor: '#020304', key: ['#ffffff', 9], rim: ['#b8d4e4', 1.6], keySize: [0.9, 0.9] },
  studio: { ground: '#0b1220', sky: '#141d2c', floor: '#06090f', key: ['#f0f4f7', 3.2], rim: ['#c8d6e1', 1.6] },
  pale: { ground: '#c9d6de', sky: '#f0f4f7', floor: '#8ea6b6', key: ['#ffffff', 2.2], rim: ['#e4eef3', 1.4] },
  highkey: {
    ground: '#9aa9b4',
    sky: '#eef3f6',
    floor: '#5f707c',
    key: ['#ffffff', 3.2],
    keySize: [4.2, 2.4],
    rim: ['#ffffff', 2.4],
    fill: ['#2a333b', 1],
    flags: '#06090c',
  },
  underwater: { ground: '#06364a', sky: '#2f7f95', floor: '#021a26', key: ['#cfeef8', 1.2], rim: ['#3a8aa0', 0.8] },
}

function proceduralScene(p: Procedural): THREE.Scene {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(p.ground)
  const mat = (hex: string, scale = 1) => new THREE.MeshBasicMaterial({ color: new THREE.Color(hex).multiplyScalar(scale), side: THREE.DoubleSide })
  // sky dome and floor: two big discs, so the gradient reads top to bottom
  const sky = new THREE.Mesh(new THREE.CircleGeometry(40, 48), mat(p.sky))
  sky.position.set(0, 12, 0)
  sky.rotation.x = Math.PI / 2
  scene.add(sky)
  const floor = new THREE.Mesh(new THREE.CircleGeometry(40, 48), mat(p.floor))
  floor.position.set(0, -6, 0)
  floor.rotation.x = -Math.PI / 2
  scene.add(floor)
  // softbox high on the left, strip light low on the right, a faint fill ahead
  const key = new THREE.Mesh(new THREE.PlaneGeometry(...(p.keySize ?? [5, 2.2])), mat(p.key[0], p.key[1]))
  key.position.set(-4, 5, 2.5)
  key.lookAt(0, 0, 0)
  scene.add(key)
  const rim = new THREE.Mesh(new THREE.PlaneGeometry(0.6, 5), mat(p.rim[0], p.rim[1]))
  rim.position.set(4.5, 1.5, -3)
  rim.lookAt(0, 0, 0)
  scene.add(rim)
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(6, 3), p.fill ? mat(p.fill[0], p.fill[1]) : mat(p.sky, 0.5))
  fill.position.set(0, 0.5, 8)
  fill.lookAt(0, 0, 0)
  scene.add(fill)
  if (p.flags) {
    for (const side of [-1, 1]) {
      const flag = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 9), mat(p.flags))
      flag.position.set(3.1 * side, 0.4, -1.4)
      flag.lookAt(0, 0.4, 0)
      scene.add(flag)
    }
  }
  return scene
}

function disposeScene(scene: THREE.Scene): void {
  scene.traverse((o) => {
    if (o instanceof THREE.Mesh) {
      o.geometry.dispose()
      ;(o.material as THREE.Material).dispose()
    }
  })
}

export function createEnvRig(renderer: THREE.WebGLRenderer): EnvRig {
  const pmrem = new THREE.PMREMGenerator(renderer)
  pmrem.compileEquirectangularShader()
  const procedural = new Map<EnvLook, THREE.WebGLRenderTarget>()
  const loaded = new Map<string, THREE.WebGLRenderTarget>()
  const requested = new Set<string>()
  let disposed = false
  const base = import.meta.env.BASE_URL

  const proceduralFor = (look: EnvLook): THREE.WebGLRenderTarget => {
    let rt = procedural.get(look)
    if (!rt) {
      const scene = proceduralScene(PROCEDURAL[look])
      // the same PMREM size as the 2048-wide equirect files (2048 / 4 = 512): the cubeUV size is part of
      // every lit material's program cache key, so a different size here would recompile every shader
      // whenever a look swaps between a file and a procedural environment (a multi-second hitch on ANGLE/D3D11)
      rt = pmrem.fromScene(scene, 0.04, 0.1, 100, { size: PMREM_SIZE })
      disposeScene(scene)
      procedural.set(look, rt)
    }
    return rt
  }

  const request = (file: string) => {
    if (requested.has(file)) return
    requested.add(file)
    // the harness (film.pending) waits for the picture the look on screen reflects
    film.pending++
    let held = true
    const settle = () => {
      if (!held) return
      held = false
      film.pending = Math.max(0, film.pending - 1)
    }
    new THREE.TextureLoader().load(
      `${base}env/${file}.webp`,
      (tex) => {
        if (disposed) {
          tex.dispose()
          settle()
          return
        }
        tex.mapping = THREE.EquirectangularReflectionMapping
        tex.colorSpace = THREE.SRGBColorSpace
        // decode off the main thread first: the PMREM upload would otherwise decode it synchronously
        const image = tex.image as HTMLImageElement
        const decoded = typeof image.decode === 'function' ? image.decode().catch(() => undefined) : Promise.resolve()
        void decoded.then(() => {
          if (disposed) {
            tex.dispose()
            settle()
            return
          }
          const rt = pmrem.fromEquirectangular(tex)
          tex.dispose()
          loaded.set(file, rt)
          // a picture that arrives for the look on screen is picked up on the next update
          current = null
          settle()
        })
      },
      undefined,
      () => {
        // missing file (pending generation): the procedural studio stays
        settle()
      },
    )
  }

  const textureFor = (look: EnvLook): THREE.Texture => {
    const file = FILES[look]
    if (!file) return proceduralFor(look).texture
    request(file)
    return (loaded.get(file) ?? proceduralFor(look)).texture
  }

  let current: EnvLook | null = null
  const rig: EnvRig = {
    texture: textureFor('void'),
    update(_renderer, weights) {
      let best: EnvLook = 'void'
      let bw = -1
      for (let i = 0; i < ENV_LOOKS.length; i++) {
        const w = weights[ENV_LOOKS[i]]
        if (w > bw) {
          bw = w
          best = ENV_LOOKS[i]
        }
      }
      if (best === current) return
      current = best
      rig.texture = textureFor(best)
    },
    prewarm() {
      const pending = ENV_LOOKS.filter((look) => FILES[look] === null && !procedural.has(look))
      const next = () => {
        const look = pending.shift()
        if (!look || disposed) return
        proceduralFor(look)
        window.setTimeout(next, 120)
      }
      window.setTimeout(next, 0)
    },
    dispose() {
      disposed = true
      for (const rt of procedural.values()) rt.dispose()
      for (const rt of loaded.values()) rt.dispose()
      procedural.clear()
      loaded.clear()
      pmrem.dispose()
    },
  }
  current = 'void'
  return rig
}
